sc_cat_item_producer.script:
/* --- VALORES DE ESTADO (Baseado no seu input) --- */
var ESTADO_REJEITADO = '4';
var ESTADO_APROVADO = '3';
var ESTADO_PENDENTE = '2';

/* --- DADOS DE ENTRADA --- */
var baseSelecionadaId = producer.base; // Nome da sua variável de Base
var usuarioAtualId = gs.getUserID(); // O usuário logado que está enviando

/*******************************************************
 * PASSO 1: VALIDAÇÃO DA HISTÓRIA 8 (Usuário Único)
 * "O usuário já tem uma inscrição ativa (Aprovada ou Pendente)?"
 *******************************************************/

// MUDE 'requested_for' para o seu campo de usuário real (ex: u_participant)
var campoUsuario = 'opened_by'; 

var grUsuario = new GlideRecord('x_1836079_office_registration');
grUsuario.addQuery(campoUsuario, usuarioAtualId); // Procura pelo usuário
grUsuario.addQuery('state', '!=', ESTADO_REJEITADO); // Onde o estado NÃO SEJA Rejeitado
grUsuario.setLimit(1); // Otimização: só precisamos de 1 para bloquear
grUsuario.query();

if (grUsuario.next()) {
    /*******************************************************
     * FALHA NA H8: O usuário já está ativo em outro lugar.
     *******************************************************/
    gs.addErrorMessage("Você já possui uma inscrição ativa ou pendente na base '" + grUsuario.getDisplayValue('base') + "'. Não é possível se registrar em duas bases.");
    current.setAbortAction(true); // Aborta a criação do registro

} else {
    /*******************************************************
     * SUCESSO NA H8: O usuário está livre.
     * Vamos checar a VALIDAÇÃO DA HISTÓRIA 7 (Lotação da Base)
     *******************************************************/

    // --- Calcular a Lotação Atual (H11) ---
    var contagemAtual = 0;
    var ga = new GlideAggregate('x_1836079_office_registration');
    ga.addQuery('base', baseSelecionadaId);
    // H11 conta Aprovados (3) e Pendentes (2)
    ga.addEncodedQuery('state=' + ESTADO_APROVADO + '^ORstate=' + ESTADO_PENDENTE);
    ga.addAggregate('COUNT');
    ga.query();

    if (ga.next()) {
        contagemAtual = ga.getAggregate('COUNT');
    }

    // --- Buscar a Lotação Máxima (H7) ---
    var maxCapacidade = 0;
    var grBase = new GlideRecord('x_1836079_office_base');
    if (grBase.get(baseSelecionadaId)) {
        maxCapacidade = parseInt(grBase.getValue('max_capacity')) || 0;
    }

    // --- A Validação de Lotação (H7) ---
    if (contagemAtual >= maxCapacidade) {
        /*******************************************************
         * FALHA NA H7: A Base está cheia.
         *******************************************************/
        gs.addErrorMessage("A base '" + grBase.getDisplayValue('name') + "' já atingiu sua lotação máxima (" + maxCapacidade + ").");
        current.setAbortAction(true); // Aborta a criação
    }
}

// Se o script chegar aqui sem entrar em nenhum 'if', o registro será criado.
